package org.jlinalg.cli;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.jlinalg.cli.NextflowFiles.*;

/** Portable full-capture/source/input replay and atomic selected scientific-contract admission. */
final class NfcoreHic210Bundle {
    private NfcoreHic210Bundle(){ }
    record Verified(Path attempt,Pin manifest,Map<?,?> audit){ }
    static void finish(Path root,String id)throws IOException{
        Path attempt=root.resolve("attempts").resolve(id);var files=new TreeMap<String,Pin>();var directories=new TreeSet<String>();census(attempt,files,directories,Set.of());writeJson(attempt.resolve("manifest.json"),Map.of("schema_version",1,"files",files,"directories",directories));Pin manifest=pin(attempt.resolve("manifest.json"),67108864,()->{});writeJson(attempt.resolve("CANDIDATE.json"),marker(manifest,"candidate"));verifyAttempt(root,id,"CANDIDATE.json");Path staged=root.resolve("completion-"+id+".new.json");writeJson(staged,marker(manifest,"complete"));Files.delete(attempt.resolve("CANDIDATE.json"));Files.move(staged,attempt.resolve("COMPLETED.json"),StandardCopyOption.ATOMIC_MOVE);
    }
    private static Map<String,Object> marker(Pin manifest,String state){return Map.of("schema_version",1,"pipeline_profile",NfcoreHic210Profile.ID,"status",state+"-original-hic-selected-scientific-contracts","manifest",manifest,"whole_paper_reproduced",false,"independent_all_fits_certified",false);}
    static Verified verify(Path supplied)throws IOException{Path root=supplied.toAbsolutePath().normalize();directory(root);var latest=NfcoreHic210Workflow.latest(root);if(!"COMPLETED".equals(latest.get("status")))throw new IOException("Latest Hi-C attempt is not complete; inspect its failure and never substitute an earlier success");return verifyAttempt(root,text(latest.get("attempt")),"COMPLETED.json");}
    private static Verified verifyAttempt(Path root,String id,String markerName)throws IOException{
        Path attempt=directory(root.resolve("attempts").resolve(id));if(Files.exists(attempt.resolve("FAILURE.json")))throw new IOException("Failed Hi-C attempt admits no result");var marker=object(json(attempt.resolve(markerName),1048576));keys(marker,"schema_version","pipeline_profile","status","manifest","whole_paper_reproduced","independent_all_fits_certified");integer(marker.get("schema_version"),1,1);String state=markerName.equals("CANDIDATE.json")?"candidate":"complete";Pin manifest=pin(attempt.resolve("manifest.json"),67108864,()->{});if(!NextflowJson.json(marker(manifest,state)).equals(NextflowJson.json(marker)))throw new IOException("Hi-C completion scope/source/manifest differs");var actual=new TreeMap<String,Pin>();var dirs=new TreeSet<String>();census(attempt,actual,dirs,Set.of(markerName,"manifest.json"));var recorded=object(json(attempt.resolve("manifest.json"),67108864));keys(recorded,"schema_version","files","directories");integer(recorded.get("schema_version"),1,1);var expected=new TreeMap<String,Pin>();for(var entry:object(recorded.get("files")).entrySet())expected.put(member(text(entry.getKey())),fingerprint(entry.getValue(),1000000000000L));if(!actual.equals(expected)||!dirs.equals(new TreeSet<>(strings(recorded.get("directories")))))throw new IOException("Whole Hi-C attempt bytes/directory census differ");
        Pin implementation=pin(root.resolve("adapter.jar"),1000000000L,()->{});NfcoreHic210Workflow.verifyContext(root,implementation);var r=NfcoreHic210Request.read(root.resolve("request.json"));var prepared=object(json(root.resolve("prepared.json"),67108864));keys(prepared,"schema_version","producer_root","source_profile","image_profile","reference_assembly_label","reference_assembly_independently_certified","input_mapping","copied_inputs","scientific_identifiers_repaired");String producer=text(prepared.get("producer_root"));NfcoreHic210Request.path(producer);if(!fingerprint(prepared.get("source_profile"),1048576).equals(NfcoreHic210Profile.SOURCE)||!fingerprint(prepared.get("image_profile"),1048576).equals(NfcoreHic210Profile.IMAGES)||!Boolean.FALSE.equals(prepared.get("reference_assembly_independently_certified"))||!Boolean.FALSE.equals(prepared.get("scientific_identifiers_repaired"))||!r.assemblyLabel().equals(prepared.get("reference_assembly_label")))throw new IOException("Original Hi-C profile/reference scope differs");
        if(!utf8(bytes(root.resolve("engine-recipe.json"),4194304)).equals(NextflowJson.json(NfcoreHic210Prepare.recipe(producer,r))+"\n"))throw new IOException("Complete Hi-C science/reference/cohort/output recipe differs");var engine=NfcoreEngineBundle.verify(root.resolve("engine"),()->{});var files=new NfcoreHic210Files(engine);var report=object(json(attempt.resolve("report.json"),67108864));keys(report,"schema_version","pipeline_profile","producer_root","engine_manifest","engine_attempt","implementation","complete_selected_original_graph_executed","independent_all_fits_certified","whole_paper_reproduced");integer(report.get("schema_version"),1,1);if(!NfcoreHic210Profile.ID.equals(report.get("pipeline_profile"))||!producer.equals(report.get("producer_root"))||!fingerprint(report.get("implementation"),1000000000L).equals(implementation)||!fingerprint(report.get("engine_manifest"),67108864).equals(engine.manifest())||!engine.attempt().getFileName().toString().equals(report.get("engine_attempt"))||!Boolean.TRUE.equals(report.get("complete_selected_original_graph_executed"))||!Boolean.FALSE.equals(report.get("independent_all_fits_certified"))||!Boolean.FALSE.equals(report.get("whole_paper_reproduced")))throw new IOException("Original source engine/report/producer binding differs");
        var materialization=files.materialization(object(json(root.resolve("materialized-index.json"),67108864)),r,producer);NfcoreHic210Export.verifyRequest(attempt,files,r);var science=NfcoreHic210Audit.run(files,r,attempt.resolve("native-export"));var audit=object(json(attempt.resolve("audit.json"),67108864));keys(audit,"materialization","scientific");if(!NextflowJson.json(Map.of("materialization",materialization,"scientific",science)).equals(NextflowJson.json(audit)))throw new IOException("Complete original Hi-C cohort/pair/bin/pixel semantic replay differs");String warnings=utf8(bytes(attempt.resolve("WARNINGS.md"),1048576));for(String value:List.of("SKIP3","FAIL2","NaN","Hashes establish integrity, not authenticity"))if(!warnings.contains(value))throw new IOException("Missing prominent Hi-C warnings/actions");return new Verified(attempt,manifest,audit);
    }
    private static void census(Path root,Map<String,Pin> files,Set<String> dirs,Set<String> excluded)throws IOException{try(var stream=Files.walk(root)){for(var iterator=stream.iterator();iterator.hasNext();){Path p=iterator.next();if(p.equals(root))continue;String name=member(root.relativize(p).toString().replace('\\','/'));if(excluded.contains(name))continue;if(Files.isSymbolicLink(p))throw new IOException("Linked Hi-C attempt member");if(Files.isDirectory(p)){directory(p);dirs.add(name);}else files.put(name,pin(p,1000000000000L,()->{}));}}}
}
